/* Shared view primitives keep search, facts and demo actions consistent across three compositions. */
window.Concepts = {};
window.H = {
  data:window.HUB_DATA,
  state:{concept:'C',page:'home',params:new URLSearchParams()},
  saved:new Set(),
  get(id){return this.data.find(r=>r.id===id);},
  pick(ids){return ids.map(id=>this.get(id)).filter(Boolean);},
  escape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));},
  normalize(value){return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();},
  searchMatches(query){const tokens=this.normalize(query).split(/\s+/).filter(Boolean);return this.data.filter(r=>tokens.every(t=>this.normalize([r.name,r.summary,r.description,r.tags||'',r.category,...r.platforms].join(' ')).includes(t)));},
  url(page='home',params={}){const query=new URLSearchParams(params).toString();return `#/${this.state.concept}/${page}${query?'?'+query:''}`;},
  symbol(name){
    const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',bookmark:'<path d="M6 4h12v17l-6-4-6 4Z"/>',grid:'<rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/>',list:'<path d="M9 6h11M9 12h11M9 18h11M4 6h.1M4 12h.1M4 18h.1"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',book:'<path d="M12 6c-3-3-7-3-10-1v14c3-2 7-2 10 1 3-3 7-3 10-1V5c-3-2-7-2-10 1Zm0 0v14"/>',work:'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="M8 6V3h8v3M3 12h18M10 12v3h4v-3"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',check:'<path d="m5 12 4 4 10-10"/>',filter:'<path d="M4 5h16M7 12h10M10 19h4"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 4H4v16h16v-6"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',heart:'<path d="M12 20 3.5 12C-2 6 6 0 12 7c6-7 14-1 8.5 5Z"/>'};
    return `<svg class="ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
  },
  brand(){return `<a class="hub-brand" href="${this.url()}"><svg width="29" height="29" viewBox="0 0 29 29" aria-hidden="true"><rect width="12" height="12" rx="4" fill="currentColor"/><rect x="17" width="12" height="12" rx="4" fill="currentColor" opacity=".6"/><rect y="17" width="12" height="12" rx="4" fill="currentColor" opacity=".6"/><path d="M17 21a4 4 0 0 1 4-4h8v8a4 4 0 0 1-4 4h-8Z" fill="currentColor"/></svg><span>nếp<span class="brand-period">.</span></span><small>thư viện số</small></a>`;},
  header(mode='standard'){
    if(this.state.concept==='A')return this.aHeader();
    const page=this.state.page;
    return `<header class="hub-header ${mode}"><div class="header-inner">${this.brand()}<nav class="hub-navigation" id="primary-nav" aria-label="Điều hướng chính"><a href="${this.url()}" ${page==='home'?'aria-current="page"':''}>Khám phá</a><a href="${this.url('discover',{category:'Học tập'})}">Học tập</a><a href="${this.url('discover',{category:'Văn phòng'})}">Làm việc</a><a href="${this.url('collection/teach')}">Bộ sưu tập</a></nav><div class="header-actions">${this.search('','header-search','Tìm tài nguyên…')}<a class="saved-link icon-button" href="${this.url('saved')}" aria-label="Mục đã lưu trong phiên">${this.symbol('bookmark')}<span data-saved-count>${this.saved.size}</span></a><button class="button contribute-button" type="button" data-open="contribute" aria-label="Đóng góp tài nguyên">${this.symbol('plus')}<span>Đóng góp</span></button><button class="icon-button nav-toggle" type="button" data-navtoggle aria-controls="primary-nav" aria-expanded="false" aria-label="Mở điều hướng">${this.symbol('menu')}</button></div></div></header>`;
  },
  aHeader(){return `<header class="hub-header editorial"><div class="header-inner">${this.brand()}<nav class="hub-navigation" id="primary-nav" aria-label="Điều hướng chính"><a href="${this.url()}" ${this.state.page==='home'?'aria-current="page"':''}>Trang chủ</a><a href="${this.url('discover')}" ${this.state.page==='discover'?'aria-current="page"':''}>Khám phá</a><a href="${this.url('about')}">Về thư viện</a></nav><div class="header-actions">${this.search('','header-search','Tìm tài nguyên…')}<a class="saved-link icon-button" href="${this.url('saved')}" aria-label="Mục đã lưu trong phiên">${this.symbol('bookmark')}<span data-saved-count>${this.saved.size}</span></a><button class="button contribute-button" type="button" data-open="contribute" aria-label="Đóng góp tài nguyên">${this.symbol('plus')}<span>Đóng góp</span></button><button class="icon-button nav-toggle" type="button" data-navtoggle aria-controls="primary-nav" aria-expanded="false" aria-label="Mở điều hướng">${this.symbol('menu')}</button></div></div></header>`;},
  simpleCard(r){return `<article class="resource-card resource-card-simple">${this.icon(r)}<h3><a href="${this.url('detail/'+r.id)}">${this.escape(r.name)}</a></h3><p>${this.escape(r.summary)}</p><a class="detail-link" href="${this.url('detail/'+r.id)}" aria-label="Tìm hiểu ${this.escape(r.name)}">Tìm hiểu ${this.symbol('arrow')}</a></article>`;},
  aResultsHead(s){return `<div class="results-block"><div class="results-heading"><p role="status"><strong>${s.filtered.length}</strong> tài nguyên${s.query?` cho “${this.escape(s.query)}”`:''}</p><label>Sắp xếp <select data-sort name="sort"><option value="editorial" ${s.params.get('sort')!=='name'?'selected':''}>Gợi ý biên tập</option><option value="name" ${s.params.get('sort')==='name'?'selected':''}>Tên A–Z</option></select></label></div></div>`;},
  footer(){return `<footer class="hub-footer"><div class="footer-top">${this.brand()}<p>Tìm đúng công cụ.<br>Dành thời gian cho điều có ích.</p><nav aria-label="Thông tin thư viện"><a href="${this.url('about')}">Về thư viện</a><a href="${this.url('contribute')}">Đề xuất tài nguyên</a><a href="${this.url('credits')}">Nguồn ảnh & giấy phép</a></nav></div><div class="footer-bottom"><span>Nếp là tên làm việc · Prototype ${this.state.concept==='A'?'P00.3':'P00.1'}</span><span>Dữ liệu minh họa, chưa phải catalog đã duyệt.</span><a href="../prototype/review.html">Xem bản P00 cũ ${this.symbol('external')}</a></div></footer>`;},
  search(value='',id='hero-search',placeholder='Bạn muốn làm gì hôm nay?'){return `<form class="hub-search" data-search role="search"><label class="sr-only" for="${id}">${this.escape(placeholder)}</label>${this.symbol('search')}<input ${this.state.concept==='A'?'data-search-trigger aria-haspopup="dialog" aria-controls="search-dialog"':''} id="${id}" type="search" name="q" maxlength="160" autocomplete="off" placeholder="${this.escape(placeholder)}" value="${this.escape(value)}"><button type="submit" aria-label="Tìm tài nguyên">${this.symbol('arrow')}</button></form>`;},
  icon(r,size='md'){
    if(r.icon)return `<span class="app-icon icon-${size}" style="--icon-tint:${r.color}"><img src="${this.state.concept==='A'&&r.id==='excalidraw'?'assets/excalidraw-responsive.svg':r.icon}" alt="" width="64" height="64"></span>`;
    const key={app:'grid',tool:'spark',repo:'code',learn:'book',game:'grid'}[r.kind];
    return `<span class="app-icon category-icon icon-${size}" style="--icon-tint:${r.color}" title="Ký hiệu loại tài nguyên, không phải logo ${this.escape(r.name)}">${this.symbol(key)}<span class="sr-only">Ký hiệu ${this.escape(r.category)}</span></span>`;
  },
  preview(r){
    if(r.screenshot)return `<figure class="product-preview preview-${r.id}"><div class="preview-image"><img src="${r.screenshot}" alt="${this.escape(r.screenshotAlt)}" width="${r.id==='godot'?1920:2000}" height="${r.id==='godot'?1080:1182}" decoding="async"></div><figcaption>Screenshot nguồn: ${r.id==='godot'?'Godot':'LocalSend'} · <a href="${this.url('credits')}">${this.escape(r.mediaCredit)}</a></figcaption></figure>`;
    if(r.artwork)return `<figure class="product-preview preview-artwork"><div class="preview-image"><img src="${r.artwork}" alt="Artwork giới thiệu Excalidraw từ kho chính thức, không phải screenshot" width="1200" height="675" decoding="async"></div><figcaption>Artwork Excalidraw · MIT · không phải screenshot · <a href="${this.url('credits')}">Nguồn</a></figcaption></figure>`;
    const learning=r.kind==='learn';
    return `<figure class="product-preview preview-diagram" style="--diagram-tint:${r.color}"><div class="workflow-art" aria-label="Sơ đồ minh họa tác vụ ${this.escape(r.name)}"><div class="workflow-top">${this.icon(r,'sm')}<span>${this.escape(r.name)}</span><span class="window-dots" aria-hidden="true">•••</span></div><div class="workflow-canvas"><div class="workflow-node">${this.symbol(learning?'book':'grid')}<span>${learning?'Tìm hiểu':'Ý tưởng'}</span></div><span class="workflow-line" aria-hidden="true"></span><div class="workflow-node central">${this.symbol(learning?'spark':'work')}<span>${learning?'Thực hành':'Bắt tay làm'}</span></div><span class="workflow-line" aria-hidden="true"></span><div class="workflow-node">${this.symbol('check')}<span>${learning?'Hiểu rõ hơn':'Kết quả'}</span></div></div><div class="workflow-bottom"><span></span><span></span><span></span></div></div><figcaption>Sơ đồ tác vụ minh họa nguyên bản · không phải giao diện sản phẩm</figcaption></figure>`;
  },
  licenseLabel(r){return this.escape(({localsend:'Apache-2.0',excalidraw:'Source MIT',godot:'Engine MIT'})[r.id]||'License chưa xác minh');},
  rating(r){if(this.state.concept==='A')return '<span class="no-rating">Chưa có đánh giá thật</span>';return r.rating?`<span class="rating"><span aria-hidden="true">★</span> ${r.rating.score.toFixed(1)} <span class="rating-count">(${r.rating.count} phiếu mẫu)</span></span>`:'<span class="no-rating">Chưa có đánh giá</span>';},
  card(r,options={}){if(options.minimal)return this.simpleCard(r);return `<article class="resource-card ${options.compact?'card-compact':''}"><div class="resource-card-top">${this.icon(r)}<button class="save-button icon-button" type="button" data-save="${r.id}" aria-pressed="${this.saved.has(r.id)}" aria-label="${this.saved.has(r.id)?'Bỏ lưu':'Lưu'} ${this.escape(r.name)} trong phiên">${this.symbol('bookmark')}</button></div><h3><a href="${this.url('detail/'+r.id)}">${this.escape(r.name)}</a></h3><p class="resource-purpose">${this.escape(r.summary)}</p><div class="resource-meta"><span>${this.escape(r.category)}</span><span title="${this.escape(r.platforms.join(', '))}">${this.escape(r.platforms.slice(0,2).join(' · '))}${r.platforms.length>2?' +':''}</span></div><p class="resource-price">${this.escape(r.price)} <span>· ${this.licenseLabel(r)}</span></p><div class="resource-card-bottom">${this.rating(r)}<a class="detail-link" href="${this.url('detail/'+r.id)}" aria-label="Xem ${this.escape(r.name)}">Xem ${this.symbol('arrow')}</a></div></article>`;},
  row(r){return `<article class="resource-row">${this.icon(r,'sm')}<div class="row-main"><h3><a href="${this.url('detail/'+r.id)}">${this.escape(r.name)}</a><span class="row-category">${this.escape(r.category)}</span></h3><p>${this.escape(r.summary)}</p><div class="row-facts"><span>${this.escape(r.platforms.join(' · '))}</span><span>${this.escape(r.price)}</span><span>${this.licenseLabel(r)}</span></div></div><div class="row-trust">${this.rating(r)}</div><a class="icon-button row-cta" href="${this.url('detail/'+r.id)}" aria-label="Xem ${this.escape(r.name)}">${this.symbol('arrow')}</a></article>`;},
  sectionHead(title,subtitle='',href){return `<div class="section-heading section-head"><div><h2>${this.escape(title)}</h2>${subtitle?`<p>${this.escape(subtitle)}</p>`:''}</div>${href?`<a class="text-link" href="${href}">Xem tất cả ${this.symbol('arrow')}</a>`:''}</div>`;},
  filters(s){
    const p=s.params,select=(name,label,items)=>`<label class="filter-field">${label}<select name="${name}">${items.map(([v,t])=>`<option value="${this.escape(v)}" ${p.get(name)===v?'selected':''}>${this.escape(t)}</option>`).join('')}</select></label>`;
    return `<form class="filter-panel" data-filters>${select('category','Nhu cầu',[['all','Mọi nhu cầu'],...['Văn phòng','Học tập','Sáng tạo','Lập trình','Bảo mật','Giải trí'].map(x=>[x,x])])}${select('kind','Loại tài nguyên',[['all','Mọi loại'],['app','Phần mềm'],['tool','Công cụ web'],['repo','Repo mã nguồn'],['learn','Học tập'],['game','Game']])}${select('platform','Nền tảng',[['all','Mọi nền tảng'],...['Web','Windows','macOS','Linux','Android','iOS'].map(x=>[x,x])])}${select('price','Chi phí',[['all','Mọi mức phí'],...['Miễn phí','Có gói miễn phí','Tùy nền tảng'].map(x=>[x,x])])}<div class="filter-actions"><button class="button" type="submit">${this.symbol('filter')}Áp dụng</button><a href="${this.url('discover',s.query?{q:s.query}:{})}">Xóa bộ lọc</a></div></form>`;
  },
  resultsHead(s){if(this.state.concept==='A')return this.aResultsHead(s);return `<div class="results-block"><div class="results-heading results-head"><p role="status"><strong>${s.filtered.length}</strong> tài nguyên${s.query?` cho “${this.escape(s.query)}”`:''}</p><label>Sắp xếp <select data-sort name="sort"><option value="editorial" ${s.params.get('sort')==='editorial'?'selected':''}>Gợi ý biên tập</option><option value="name" ${s.params.get('sort')==='name'?'selected':''}>Tên A–Z</option><option value="rating" ${s.params.get('sort')==='rating'?'selected':''}>Điểm mẫu có trọng số</option></select></label></div>${s.params.get('sort')==='rating'?'<p class="fixture-rating-note">Điểm/số phiếu chỉ là fixture UI. Thứ tự dùng trung bình Bayesian mẫu (C=4, m=20); chưa có đánh giá cộng đồng thật.</p>':''}</div>`;},
  empty(s){return `<div class="empty-state">${this.symbol('search')}<h2>Chưa có lựa chọn phù hợp.</h2><p>Thử từ khóa ngắn hơn hoặc bỏ bớt bộ lọc.<br>Ví dụ: chuyển tệp, sơ đồ, học lập trình.</p><a class="button" href="${this.url('discover')}">Xem toàn bộ thư viện ${this.symbol('arrow')}</a></div>`;},
  facts(r){return `<dl class="resource-facts"><div><dt>Phù hợp với</dt><dd>${this.escape(r.audience)}</dd></div><div><dt>Nền tảng</dt><dd>${this.escape(r.platforms.join(', '))}</dd></div><div><dt>Chi phí minh họa</dt><dd>${this.escape(r.price)}</dd></div><div><dt>Giấy phép</dt><dd>${this.escape(r.license)}</dd></div><div><dt>Đánh giá</dt><dd>${this.rating(r)}</dd></div><div><dt>Kiểm chứng nội dung</dt><dd>Fixture P00.1 · chưa dùng thử</dd></div></dl>`;},
  article(r){return `<div class="editorial-article"><section><h2>Một công cụ cho việc gì?</h2><p>${this.escape(r.description)}</p></section><section><h2>Bạn có thể bắt đầu từ đây</h2><ul>${r.benefits.map(x=>`<li>${this.escape(x)}</li>`).join('')}</ul></section><section><h2>Điều cần biết trước khi dùng</h2><ul>${r.cautions.map(x=>`<li>${this.escape(x)}</li>`).join('')}</ul></section><section class="source-note"><h2>Nguồn và tính minh bạch</h2><p>Đây là nội dung mẫu để review UI, chưa phải bài đánh giá đã biên tập. Giá, nền tảng, giấy phép và khả năng thực tế cần kiểm tại nguồn trước khi công bố.</p><a href="${r.homepage}" target="_blank" rel="noopener noreferrer">Website chính thức ${this.symbol('external')}</a>${r.repo?`<a href="${r.repo}" target="_blank" rel="noopener noreferrer">Kho mã nguồn ${this.symbol('code')}</a>`:''}<button type="button" class="text-button" data-report="${r.id}">Báo thông tin cần kiểm tra</button></section></div>`;},
  related(r){const candidates=this.data.filter(x=>x.id!==r.id&&x.category===r.category);const rows=(candidates.length?candidates:this.data.filter(x=>x.id!==r.id)).slice(0,3);return `<section class="related-section">${this.sectionHead('Có thể bạn cũng cần','Một vài hướng khám phá tiếp theo.',this.url('discover',{category:r.category}))}<div class="cards-grid">${rows.map(x=>this.card(x,{minimal:this.state.concept==='A'})).join('')}</div></section>`;},
  collections(){return `<div class="collection-grid">${window.HUB_COLLECTIONS.map(c=>`<a class="collection-card collection-${c.tone}" href="${this.url('collection/'+c.id)}"><span class="collection-symbol">${this.symbol(c.symbol)}</span><span class="eyebrow">${this.escape(c.label)}</span><h3>${this.escape(c.title)}</h3><p>${this.escape(c.summary)}</p><span class="collection-bottom">${c.ids.length} tài nguyên mẫu ${this.symbol('arrow')}</span></a>`).join('')}</div>`;}
};
